import os
import torch


class Config:
    """
    Central configuration for the Multi-Task EfficientDet-D3 solution (Idea 4).
    """

    # =========================================================================
    # File Paths & Directories
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the provided script
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for this specific idea
    WORKING_DIR = "./working/idea_4"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")

    # Model checkpoints and output
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =========================================================================
    # Data Hyperparameters
    # =========================================================================
    IMG_SIZE = 640  # Resolution for EfficientNet-B3 / EfficientDet-D3
    NUM_WORKERS = 4  # Number of dataloader workers
    BATCH_SIZE = 16  # Fits comfortably on A100-40GB with 640x640

    # Class Definitions
    STUDY_CLASSES = [
        "Negative for Pneumonia",
        "Typical Appearance",
        "Indeterminate Appearance",
        "Atypical Appearance",
    ]
    NUM_STUDY_CLASSES = len(STUDY_CLASSES)

    # Detection class (1 foreground class: opacity)
    DETECTION_CLASSES = ["opacity"]
    NUM_DETECTION_CLASSES = len(DETECTION_CLASSES)

    # =========================================================================
    # Model Hyperparameters
    # =========================================================================
    BACKBONE = "efficientnet-b3"
    PRETRAINED = True

    # Anchor parameters (if custom anchors are needed, otherwise defaults used)
    ANCHOR_SCALES = [2**0, 2 ** (1.0 / 3.0), 2 ** (2.0 / 3.0)]
    ANCHOR_RATIOS = [0.5, 1.0, 2.0]

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    SEED = 42
    EPOCHS = 15
    LEARNING_RATE = 3e-4
    WEIGHT_DECAY = 1e-4

    # Scheduler
    T_MAX = EPOCHS  # For CosineAnnealingLR
    ETA_MIN = 1e-6

    # Early Stopping
    PATIENCE = 4

    # Loss Weights
    # L_total = L_box + L_cls + lambda * L_study
    LAMBDA_STUDY = 1.0

    # Inference
    IOU_THRESHOLD = 0.5  # For NMS and mAP calculation
    CONF_THRESHOLD = 0.001  # Confidence threshold for keeping boxes
    STUDY_CONF_THRESHOLD = 0.5  # Threshold to override detection with "none"

    # =========================================================================
    # System
    # =========================================================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def setup(cls):
        """
        Ensures necessary directories exist.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)


# Execute setup immediately upon import to ensure paths exist
Config.setup()
